// If your answer is "I write production-quality code," this is evidence:
// Code that actually handles edge cases and error scenarios

@RestController
@RequestMapping("/api/payments")
public class PaymentController {
    private final PaymentService paymentService;

    public PaymentController(PaymentService paymentService) {
        this.paymentService = paymentService;
    }

    @PostMapping
    public ResponseEntity<PaymentResponse> processPayment(@Valid @RequestBody PaymentRequest request) {
        try {
            var result = paymentService.process(request);
            return ResponseEntity.ok(result);
        } catch (InsufficientFundsException e) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new PaymentResponse("FAILED", e.getMessage()));
        } catch (PaymentGatewayException e) {
            return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE)
                .body(new PaymentResponse("RETRY", "Service temporarily unavailable"));
        }
    }
}

// This shows: proper error handling, meaningful HTTP status codes, validation
// Not just happy-path code that freshers typically write
