// You differentiate by showing you've handled real-world complexity:

@Service
public class OrderService {
    private final OrderRepository orderRepository;
    private final InventoryClient inventoryClient;
    private final PaymentService paymentService;

    @Transactional
    public OrderResponse createOrder(OrderRequest request) {
        // Check inventory before creating order (coordination with external service)
        if (!inventoryClient.checkAvailability(request.productId(), request.quantity())) {
            throw new OutOfStockException("Product unavailable");
        }

        var order = new Order(request.userId(), request.productId(), request.quantity());
        var saved = orderRepository.save(order);

        // If payment fails, transaction rolls back the order save
        paymentService.processPayment(saved.id(), request.amount());

        return new OrderResponse(saved.id(), "SUCCESS");
    }
}

// This shows: transaction management, external service coordination, error scenarios
// You can say: "I've handled multi-step transactions with rollback logic, not just CRUD"
